css:
.sl-faq-simple-list { padding-block: clamp(3rem, 6vw, 5rem); padding-inline: clamp(1rem, 4vw, 2rem); width: 100%; font-family: var(--smartlearn-body-font, system-ui, sans-serif); background-color: var(--smartlearn-bg); }
.sl-faq-simple-list .sl-container { max-width: 800px; margin-inline: auto; }
.sl-faq-simple-list .sl-header { text-align: center; margin-bottom: clamp(2.5rem, 5vw, 4rem); }
.sl-faq-simple-list .sl-title { font-size: clamp(1.85rem, 3.5vw, 2.5rem); font-weight: 800; color: var(--smartlearn-text); margin-bottom: 1rem; font-family: var(--smartlearn-heading-font, inherit); }
.sl-faq-simple-list .sl-subtitle { font-size: 1.125rem; color: var(--smartlearn-text-muted); line-height: 1.6; margin: 0; }
.sl-faq-simple-list .sl-list { display: flex; flex-direction: column; gap: 2.5rem; }
.sl-faq-simple-list .sl-item { border-bottom: 1px solid var(--smartlearn-card-border, rgba(148, 163, 184, 0.25)); padding-bottom: 2.5rem; }
.sl-faq-simple-list .sl-item:last-child { border-bottom: none; padding-bottom: 0; }
.sl-faq-simple-list .sl-q { font-family: var(--smartlearn-heading-font, inherit); font-size: 1.25rem; font-weight: 600; color: var(--smartlearn-text); margin-bottom: 1rem; }
.sl-faq-simple-list .sl-a { font-size: 1rem; color: var(--smartlearn-text-muted); line-height: 1.7; margin: 0; }
